// Intl tests: expected values are what Chrome (V8 13.6 / ICU 78) prints.
// Generated from node's Intl and checked against intl.js.
'use strict';

test("DateTimeFormat: en-US defaults and toLocale*", () => {
  assertEq(new Date(Date.UTC(2026, 10, 7, 17, 5, 9)).toLocaleString('en-US', { timeZone: 'America/Los_Angeles' }), "11/7/2026, 9:05:09 AM");
  assertEq(new Date(Date.UTC(2026, 10, 7, 17, 5, 9)).toLocaleDateString('en-US', { timeZone: 'America/Los_Angeles' }), "11/7/2026");
  assertEq(new Date(Date.UTC(2026, 10, 7, 17, 5, 9)).toLocaleTimeString('en-US', { timeZone: 'America/Los_Angeles' }), "9:05:09 AM");
  assertEq(new Date(Date.UTC(2026, 10, 7, 17, 5, 9)).toLocaleString('en-US', { timeZone: 'UTC' }), "11/7/2026, 5:05:09 PM");
  assertEq(new Date(Date.UTC(2026, 10, 7, 17, 5, 9)).toLocaleString('en-US', { timeZone: 'Europe/Berlin' }), "11/7/2026, 6:05:09 PM");
  assertEq(new Date(Date.UTC(2026, 10, 7, 17, 5, 9)).toLocaleString('en-US', { timeZone: 'Asia/Kolkata' }), "11/7/2026, 10:35:09 PM");
  assertEq(new Intl.DateTimeFormat('en-US', { timeZone: 'UTC' }).format(Date.UTC(2026, 10, 7, 17, 5, 9)), "11/7/2026");
  assertEq(new Intl.DateTimeFormat('en-US', { timeZone: 'America/Los_Angeles', dateStyle: 'full', timeStyle: 'long' }).format(Date.UTC(2026, 10, 7, 17, 5, 9)), "Saturday, November 7, 2026 at 9:05:09 AM PST");
  assertEq(new Intl.DateTimeFormat('en-US', { timeZone: 'America/Los_Angeles', dateStyle: 'long', timeStyle: 'short' }).format(Date.UTC(2026, 10, 7, 17, 5, 9)), "November 7, 2026 at 9:05 AM");
  assertEq(new Intl.DateTimeFormat('en-US', { timeZone: 'America/Los_Angeles', dateStyle: 'medium', timeStyle: 'short' }).format(Date.UTC(2026, 10, 7, 17, 5, 9)), "Nov 7, 2026, 9:05 AM");
  assertEq(new Intl.DateTimeFormat('en-US', { timeZone: 'America/Los_Angeles', dateStyle: 'short', timeStyle: 'short' }).format(Date.UTC(2026, 10, 7, 17, 5, 9)), "11/7/26, 9:05 AM");
  assertEq(new Intl.DateTimeFormat('en-US', { timeZone: 'Asia/Kolkata', dateStyle: 'full', timeStyle: 'full' }).format(Date.UTC(2026, 10, 7, 17, 5, 9)), "Saturday, November 7, 2026 at 10:35:09 PM India Standard Time");
  assertEq(new Intl.DateTimeFormat('en-US', { timeZone: 'Europe/Berlin', timeStyle: 'full' }).format(Date.UTC(2026, 10, 7, 17, 5, 9)), "6:05:09 PM Central European Standard Time");
  assertEq(new Date(Date.UTC(2026, 10, 7, 17, 5, 9)).toLocaleDateString('en-US', { timeZone: 'UTC', month: 'short', day: 'numeric' }), "Nov 7");
  assertEq(new Date(Date.UTC(2026, 10, 7, 17, 5, 9)).toLocaleDateString('en-US', { timeZone: 'UTC', month: 'short', day: 'numeric', year: 'numeric' }), "Nov 7, 2026");
  assertEq(new Date(Date.UTC(2026, 10, 7, 17, 5, 9)).toLocaleDateString('en-US', { timeZone: 'UTC', weekday: 'long', month: 'long', day: 'numeric' }), "Saturday, November 7");
  assertEq(new Date(Date.UTC(2026, 10, 7, 17, 5, 9)).toLocaleString('en-US', { timeZone: 'UTC', month: 'long', day: 'numeric', hour: 'numeric', minute: '2-digit' }), "November 7 at 5:05 PM");
  assertEq(new Date(Date.UTC(2026, 10, 7, 17, 5, 9)).toLocaleString('en-US', { timeZone: 'UTC', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }), "Nov 7, 5:05 PM");
  assertEq(new Date(Date.UTC(2026, 10, 7, 17, 5, 9)).toLocaleString('en-US', { timeZone: 'UTC', weekday: 'short', hour: 'numeric', minute: '2-digit' }), "Sat 5:05 PM");
  assertEq(new Date(Date.UTC(2026, 10, 7, 17, 5, 9)).toLocaleTimeString('en-US', { timeZone: 'UTC', hour: 'numeric', minute: '2-digit' }), "5:05 PM");
  assertEq(new Date(Date.UTC(2026, 10, 7, 17, 5, 9)).toLocaleTimeString('en-US', { timeZone: 'UTC', hour: '2-digit', minute: '2-digit', hour12: false }), "17:05");
  assertEq(new Date(Date.UTC(2026, 10, 7, 17, 5, 9)).toLocaleTimeString('en-US', { timeZone: 'UTC', hourCycle: 'h23' }), "17:05:09");
  assertEq(new Date(Date.UTC(2026, 10, 7, 17, 5, 9)).toLocaleString('en-US', { timeZone: 'UTC', year: '2-digit', month: '2-digit', day: '2-digit' }), "11/07/26");
  assertEq(new Date(Date.UTC(2026, 10, 7, 17, 5, 9)).toLocaleString('en-US', { timeZone: 'America/Los_Angeles', timeZoneName: 'short' }), "11/7/2026, 9:05:09 AM PST");
  assertEq(new Date(Date.UTC(2026, 10, 7, 17, 5, 9)).toLocaleString('en-US', { timeZone: 'America/New_York', hour: 'numeric', timeZoneName: 'long' }), "12 PM Eastern Standard Time");
  assertEq(new Date(Date.UTC(2026, 10, 7, 17, 5, 9)).toLocaleString('en-US', { timeZone: 'Asia/Kolkata', hour: 'numeric', timeZoneName: 'shortOffset' }), "10 PM GMT+5:30");
  assertEq(new Date(Date.UTC(2026, 10, 7, 17, 5, 9)).toLocaleString('en-US', { timeZone: 'Asia/Kolkata', hour: 'numeric', timeZoneName: 'longOffset' }), "10 PM GMT+05:30");
  assertEq(new Date(Date.UTC(2026, 10, 7, 17, 5, 9)).toLocaleString('en-US', { timeZone: 'America/Los_Angeles', hour: 'numeric', timeZoneName: 'shortGeneric' }), "9 AM PT");
  assertEq(new Date(Date.UTC(2026, 10, 7, 17, 5, 9)).toLocaleString('en-US', { timeZone: 'America/Los_Angeles', hour: 'numeric', timeZoneName: 'longGeneric' }), "9 AM Pacific Time");
  assertEq(new Date(Date.UTC(2026, 10, 7, 17, 5, 9)).toLocaleString('en-US', { timeZone: '+05:30', timeZoneName: 'short' }), "11/7/2026, 10:35:09 PM GMT+5:30");
  assertEq(new Date(Date.UTC(2026, 10, 7, 17, 5, 9)).toLocaleString('en-US', { timeZone: 'Etc/GMT+5', timeZoneName: 'short' }), "11/7/2026, 12:05:09 PM GMT-5");
  assertEq(new Date(Date.UTC(2026, 10, 7, 17, 5, 9)).toLocaleString('en-US', { timeZone: 'UTC', timeZoneName: 'short' }), "11/7/2026, 5:05:09 PM UTC");
  assertEq(new Date(Date.UTC(2026, 10, 7, 17, 5, 9)).toLocaleString('en-US', { timeZone: 'UTC', hour: 'numeric', dayPeriod: 'long' }), "5 in the afternoon");
  assertEq(new Date(Date.UTC(2026, 10, 7, 17, 5, 9)).toLocaleString('en-US', { timeZone: 'UTC', era: 'short', year: 'numeric' }), "2026 AD");
  assertEq(new Date(Date.UTC(2026, 10, 7, 17, 5, 9)).toLocaleString('en-US', { timeZone: 'UTC', minute: '2-digit', second: '2-digit', fractionalSecondDigits: 3 }), "05:09.000");
  assertEq(new Date(Date.UTC(-100, 0, 1)).toLocaleDateString('en-US', { timeZone: 'UTC', year: 'numeric', era: 'short' }), "101 BC");
  assertEq(new Date(NaN).toLocaleString(), "Invalid Date");
});

