  assertEq(new Intl.DateTimeFormat('en-GB', { timeZone: 'UTC', dateStyle: 'medium' }).format(Date.UTC(2026, 10, 7, 17, 5, 9)), "7 Nov 2026");
  assertEq(new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Kolkata', month: 'long', day: 'numeric', hour: 'numeric', minute: 'numeric' }).format(Date.UTC(2026, 10, 7, 17, 5, 9)), "7 November at 22:35");
