  assertEq(new Intl.DateTimeFormat('en-GB', { timeZone: 'utc', dateStyle: 'short', timeStyle: 'short' }).resolvedOptions(), {"locale":"en-GB","calendar":"gregory","numberingSystem":"latn","timeZone":"UTC","hourCycle":"h23","hour12":false,"dateStyle":"short","timeStyle":"short"});
  assertEq(new Intl.DateTimeFormat('de', { timeZone: 'Europe/Berlin', hour: 'numeric', hour12: true }).resolvedOptions(), {"locale":"de","calendar":"gregory","numberingSystem":"latn","timeZone":"Europe/Berlin","hourCycle":"h12","hour12":true,"hour":"numeric"});
  assertEq(new Intl.DateTimeFormat('ja', { timeZone: 'Asia/Tokyo', hour: 'numeric', minute: 'numeric', weekday: 'short' }).resolvedOptions(), {"locale":"ja","calendar":"gregory","numberingSystem":"latn","timeZone":"Asia/Tokyo","hourCycle":"h23","hour12":false,"weekday":"short","hour":"numeric","minute":"2-digit"});
