test("NumberFormat: units and ranges", () => {
  assertEq(new Intl.NumberFormat('en-US', { style: 'unit', unit: 'kilobyte' }).format(1536), "1,536 kB");
  assertEq(new Intl.NumberFormat('en-US', { style: 'unit', unit: 'megabyte', unitDisplay: 'long' }).format(1), "1 megabyte");
  assertEq(new Intl.NumberFormat('en-US', { style: 'unit', unit: 'megabyte', unitDisplay: 'long' }).format(2.5), "2.5 megabytes");
  assertEq(new Intl.NumberFormat('en-US', { style: 'unit', unit: 'gigabyte', unitDisplay: 'narrow' }).format(3), "3GB");
  assertEq(new Intl.NumberFormat('en-US', { style: 'unit', unit: 'second', unitDisplay: 'long' }).format(1), "1 second");
  assertEq(new Intl.NumberFormat('en-US', { style: 'unit', unit: 'minute', unitDisplay: 'short' }).format(5), "5 min");
  assertEq(new Intl.NumberFormat('en-US', { style: 'unit', unit: 'hour', unitDisplay: 'narrow' }).format(5), "5h");
  assertEq(new Intl.NumberFormat('en-US', { style: 'unit', unit: 'day', unitDisplay: 'long' }).format(3), "3 days");
  assertEq(new Intl.NumberFormat('en-US', { style: 'unit', unit: 'percent' }).format(42), "42%");
  assertEq(new Intl.NumberFormat('en-US', { style: 'unit', unit: 'kilometer-per-hour' }).format(50), "50 km/h");
  assertEq(new Intl.NumberFormat('en-US', { style: 'unit', unit: 'kilometer-per-hour', unitDisplay: 'long' }).format(50), "50 kilometers per hour");
  assertEq(new Intl.NumberFormat('de', { style: 'unit', unit: 'kilobyte', unitDisplay: 'long' }).format(3), "3 Kilobyte");
  assertEq(new Intl.NumberFormat('ru', { style: 'unit', unit: 'kilobyte', unitDisplay: 'long' }).format(5), "5 килобайт");
  assertEq(new Intl.NumberFormat('ja', { style: 'unit', unit: 'kilobyte' }).format(5), "5 KB");
  assertEq(new Intl.NumberFormat('en-US', { style: 'unit', unit: 'byte' }).formatToParts(5), [{"type":"integer","value":"5"},{"type":"literal","value":" "},{"type":"unit","value":"byte"}]);
  assertEq(new Intl.NumberFormat('en-US').formatRange(1, 5), "1–5");
  assertEq(new Intl.NumberFormat('en-US').formatRange(3, 3), "~3");
  assertEq(new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).formatRange(1, 5), "$1.00 – $5.00");
  assertEq(new Intl.NumberFormat('de', { style: 'currency', currency: 'EUR' }).formatRange(1, 5), "1,00–5,00 €");
  assertEq(new Intl.NumberFormat('en-US', { style: 'unit', unit: 'kilometer' }).formatRange(1, 5), "1–5 km");
  assertEq(new Intl.NumberFormat('en-US', { style: 'percent' }).formatRange(0.01, 0.05), "1% – 5%");
  assertEq(new Intl.NumberFormat('en-US').formatRange(-5, -1), "-5 – -1");
  assertEq(new Intl.NumberFormat('en-US').formatRangeToParts(1, 5), [{"type":"integer","value":"1","source":"startRange"},{"type":"literal","value":"–","source":"shared"},{"type":"integer","value":"5","source":"endRange"}]);
});

