  assertEq(new Intl.NumberFormat('de', { style: 'currency', currency: 'eur' }).resolvedOptions(), {"locale":"de","numberingSystem":"latn","style":"currency","currency":"EUR","currencyDisplay":"symbol","currencySign":"standard","minimumIntegerDigits":1,"minimumFractionDigits":2,"maximumFractionDigits":2,"useGrouping":"auto","notation":"standard","signDisplay":"auto","roundingIncrement":1,"roundingMode":"halfExpand","roundingPriority":"auto","trailingZeroDisplay":"auto"});
  assertEq(new Intl.NumberFormat('en-US', { style: 'unit', unit: 'byte', maximumSignificantDigits: 3 }).resolvedOptions(), {"locale":"en-US","numberingSystem":"latn","style":"unit","unit":"byte","unitDisplay":"short","minimumIntegerDigits":1,"minimumSignificantDigits":1,"maximumSignificantDigits":3,"useGrouping":"auto","notation":"standard","signDisplay":"auto","roundingIncrement":1,"roundingMode":"halfExpand","roundingPriority":"auto","trailingZeroDisplay":"auto"});
