  assertEq(['en', 'en-US', 'fr', 'de', 'es', 'ja', 'zh', 'ko', 'ru', 'pt-BR', 'it', 'nl', 'ar', 'hi'].map((c) => new Intl.DisplayNames('ja', { type: 'language' }).of(c)), ["英語","アメリカ英語","フランス語","ドイツ語","スペイン語","日本語","中国語","韓国語","ロシア語","ポルトガル語 (ブラジル)","イタリア語","オランダ語","アラビア語","ヒンディー語"]);
