  assertEq(['US', 'GB', 'DE', 'FR', 'JP', 'CN'].map((c) => new Intl.DisplayNames('fr', { type: 'region' }).of(c)), ["États-Unis","Royaume-Uni","Allemagne","France","Japon","Chine"]);
