test("DurationFormat", () => {
  assertEq(new Intl.DurationFormat('en', { style: 'short' }).format({ hours: 1, minutes: 46, seconds: 40 }), "1 hr, 46 min, 40 sec");
  assertEq(new Intl.DurationFormat('en', { style: 'long' }).format({ hours: 1, minutes: 46, seconds: 40 }), "1 hour, 46 minutes, 40 seconds");
  assertEq(new Intl.DurationFormat('en', { style: 'narrow' }).format({ hours: 1, minutes: 46, seconds: 40 }), "1h 46m 40s");
  assertEq(new Intl.DurationFormat('en', { style: 'digital' }).format({ hours: 1, minutes: 46, seconds: 40 }), "1:46:40");
  assertEq(new Intl.DurationFormat('en', { style: 'long' }).format({ days: 2, milliseconds: 5 }), "2 days, 5 milliseconds");
  assertEq(new Intl.DurationFormat('de', { style: 'long' }).format({ hours: 2, minutes: 1 }), "2 Stunden, 1 Minute");
});

test("Locale and canonicalization", () => {
  assertEq(Intl.getCanonicalLocales(['EN-us', 'zh-hant-tw', 'iw', 'en-US-u-kn-true', 'de-de-u-co-phonebk']), ["en-US","zh-Hant-TW","he","en-US-u-kn","de-DE-u-co-phonebk"]);
  assertEq(Intl.getCanonicalLocales('EN-gb-oxendict-x-foo'), ["en-GB-oxendict-x-foo"]);
  assertEq((l => [l.toString(), l.baseName, l.language, l.script, l.region, l.calendar, l.hourCycle, l.numeric])(new Intl.Locale('en-Latn-US-u-ca-gregory-hc-h12-kn')), ["en-Latn-US-u-ca-gregory-hc-h12-kn","en-Latn-US","en","Latn","US","gregory","h12",true]);
  assertEq([new Intl.Locale('en').maximize().toString(), new Intl.Locale('zh-TW').maximize().toString(), new Intl.Locale('zh-Hant-TW').minimize().toString(), new Intl.Locale('en-Latn-US').minimize().toString(), new Intl.Locale('ja').maximize().toString()], ["en-Latn-US","zh-Hant-TW","zh-TW","en","ja-Jpan-JP"]);
  assertEq(new Intl.Locale('en', { region: 'GB', hourCycle: 'h23' }).toString(), "en-GB-u-hc-h23");
  assertEq(new Intl.Locale('en-US').getWeekInfo().firstDay, 7);
  assertEq(new Intl.Locale('de-DE').getWeekInfo().firstDay, 1);
  assertEq(Intl.DateTimeFormat.supportedLocalesOf(['en-US', 'de-AT', 'fr', 'ja-JP']), ["en-US","de-AT","fr","ja-JP"]);
  assertEq(['en-US', 'en', 'de-AT', 'pt', 'en-u-hc-h23', 'fr-CA'].map((l) => new Intl.NumberFormat(l).resolvedOptions().locale), ["en-US","en","de-AT","pt","en","fr-CA"]);
  assertEq(new Intl.NumberFormat('xx').resolvedOptions().locale, "en-US");
  assertEq(Object.prototype.toString.call(Intl), "[object Intl]");
  assertEq(Object.prototype.toString.call(new Intl.DateTimeFormat()), "[object Intl.DateTimeFormat]");
  assertEq([typeof Intl.DateTimeFormat.prototype.formatToParts, Intl.NumberFormat.length, Intl.DisplayNames.length, Intl.Locale.length], ["function",0,2,1]);
  assertEq(Intl.supportedValuesOf('timeZone').includes('America/Los_Angeles'), true);
  assertEq(Intl.supportedValuesOf('currency').includes('USD'), true);
  assertEq(Intl.supportedValuesOf('unit').includes('kilobyte'), true);
  assertEq('TITLE'.toLocaleLowerCase('tr'), "tıtle");
  assertEq('title'.toLocaleUpperCase('tr'), "TİTLE");
  assertEq([1234.5, new Date(Date.UTC(2026, 10, 7, 17, 5, 9))].toLocaleString('de', { timeZone: 'UTC' }), "1.234,5,7.11.2026, 17:05:09");
});

