test('V8 swaps U+202F for a space in format() but not in formatToParts', () => {
  const f = new Intl.DateTimeFormat('en-US', { timeZone: 'UTC', hour: 'numeric', minute: '2-digit' });
  const t = Date.UTC(2026, 10, 7, 17, 5, 9);
  assertEq(f.format(t), '5:05 PM');
  assertEq(f.formatToParts(t).map((p) => p.value).join(''), '5:05\u202FPM');
  assertEq(new Date(t).toLocaleTimeString('en-US', { timeZone: 'UTC' }), '5:05:09 PM');
});

test('errors', async () => {
  await assertThrows(() => new Intl.DateTimeFormat('en', { timeZone: 'Foo/Bar' }), 'RangeError');
  await assertThrows(() => new Intl.DateTimeFormat('en', { dateStyle: 'full', month: 'long' }), 'TypeError');
  await assertThrows(() => new Intl.DateTimeFormat('en').format(NaN), 'RangeError');
  await assertThrows(() => new Intl.DateTimeFormat('en', { weekday: 'bogus' }), 'RangeError');
  await assertThrows(() => new Date().toLocaleDateString('en', { timeStyle: 'short' }), 'TypeError');
  await assertThrows(() => new Intl.NumberFormat('en', { style: 'currency' }), 'TypeError');
  await assertThrows(() => new Intl.NumberFormat('en', { style: 'currency', currency: 'US' }), 'RangeError');
  await assertThrows(() => new Intl.NumberFormat('en', { style: 'unit', unit: 'parsec' }), 'RangeError');
  await assertThrows(() => new Intl.NumberFormat('en', { maximumFractionDigits: 200 }), 'RangeError');
  await assertThrows(() => new Intl.RelativeTimeFormat('en').format(1, 'decade'), 'RangeError');
  await assertThrows(() => new Intl.RelativeTimeFormat('en').format(Infinity, 'day'), 'RangeError');
  await assertThrows(() => Intl.PluralRules(), 'TypeError');
  await assertThrows(() => new Intl.DisplayNames('en'), 'TypeError');
  await assertThrows(() => new Intl.DisplayNames('en', { type: 'region' }).of('U'), 'RangeError');
  await assertThrows(() => Intl.getCanonicalLocales('en_US'), 'RangeError');
  await assertThrows(() => new Intl.ListFormat('en').format(['a', 1]), 'TypeError');
  await assertThrows(() => Intl.supportedValuesOf('bogus'), 'RangeError');
  await assertThrows(() => Intl.DateTimeFormat.prototype.format.call({}), 'TypeError');
});

test('legacy constructors work without new; the rest need it', () => {
  assertEq(Intl.DateTimeFormat('en', { timeZone: 'UTC' }).format(0), '1/1/1970');
  assertEq(Intl.NumberFormat('de').format(1234.5), '1.234,5');
  assertEq(typeof Intl.Collator().compare, 'function');
  assert(Intl.DateTimeFormat() instanceof Intl.DateTimeFormat);
  class Sub extends Intl.NumberFormat {}
  assertEq(new Sub('en').format(1e3), '1,000');
});

test('bound format/compare getters are stable', () => {
  const f = new Intl.NumberFormat('en');
  assert(f.format === f.format);
  assertEq([1, 2000].map(f.format), ['1', '2,000']);
  const c = new Intl.Collator('en');
  assertEq(['b', 'a'].sort(c.compare), ['a', 'b']);
});

test('Taut: LastSeen ago()', () => {
  const format = new Intl.RelativeTimeFormat(undefined, { numeric: 'auto' });
  assertEq(format.format(-1, 'day'), 'yesterday');
  assertEq(format.format(-3, 'hour'), '3 hours ago');
  assertEq(format.format(-1, 'minute'), '1 minute ago');
});

test('Taut: schedule toWall() round-trips through formatToParts', () => {
  const formatters = new Map();
  const toWall = (instant, timeZone) => {
    let format = formatters.get(timeZone);
    if (!format) {
      format = new Intl.DateTimeFormat('en-US', { timeZone, hourCycle: 'h23', year: 'numeric', month: 'numeric', day: 'numeric', hour: 'numeric', minute: 'numeric', second: 'numeric' });
      formatters.set(timeZone, format);
    }
    const part = {};
    for (const { type, value } of format.formatToParts(instant)) part[type] = Number(value);
    return Date.UTC(part.year, part.month - 1, part.day, part.hour, part.minute) + part.second * 1000 + (instant % 1000);
  };
  const t = Date.UTC(2026, 10, 7, 17, 5, 9);
  assertEq(toWall(t, 'UTC'), t);
  assertEq(toWall(t, 'America/Los_Angeles'), t - 8 * 3600e3);
  assertEq(toWall(t, 'Asia/Kolkata'), t + 5.5 * 3600e3);
  assertEq(toWall(Date.UTC(2026, 6, 1, 12), 'Europe/Berlin'), Date.UTC(2026, 6, 1, 14));
  // midnight is hour 0 in h23
  assertEq(toWall(Date.UTC(2026, 0, 1, 0), 'UTC'), Date.UTC(2026, 0, 1, 0));
});

test('Taut: HuddleActivity languageName and BetterTypingIndicator graphemes', () => {
  const languageName = (locale) => new Intl.DisplayNames([navigator.language], { type: 'language' }).of(locale) ?? locale;
  assertEq(languageName('es'), 'Spanish');
  assertEq(languageName('en-US'), 'American English');
  assertEq(languageName('zh-Hans'), 'Simplified Chinese');
  const graphemes = new Intl.Segmenter(undefined, { granularity: 'grapheme' });
  assertEq([...graphemes.segment('typing… 👩‍💻🇫🇷')].length, 10);
});

test('Taut: Experiments / pluginManager / Nicknames', () => {
  assertEq((12345).toLocaleString(), '12,345');
  assertEq(['b', 'A', 'a', 'B'].sort((a, b) => a.localeCompare(b, undefined, { sensitivity: 'base' })), ['A', 'a', 'b', 'B']);
  assertEq(['Zed', 'alice', 'Bob'].sort((a, b) => a.localeCompare(b)), ['alice', 'Bob', 'Zed']);
});

test('default locale, time zone and toLocaleString defaults', () => {
  assertEq(new Intl.NumberFormat().resolvedOptions().locale, 'en-US');
  const ro = new Intl.DateTimeFormat().resolvedOptions();
  assertEq(ro.locale, 'en-US');
  assertEq(typeof ro.timeZone, 'string');
  assert(ro.timeZone.length > 0);
  assert(/^\d{1,2}\/\d{1,2}\/\d{4}, \d{1,2}:\d\d:\d\d [AP]M$/.test(new Date().toLocaleString()), new Date().toLocaleString());
  assert(/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(new Date().toLocaleDateString()));
  assertEq(new Date(Date.UTC(2026, 0, 1)).toLocaleDateString(undefined, { timeZone: 'UTC', month: 'short', day: 'numeric' }), 'Jan 1');
});

test('performance: cached toLocale*, long segmenting, big sorts', () => {
  let t0 = performance.now();
  for (let i = 0; i < 2000; i++) new Date(i * 86400e3).toLocaleDateString('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' });
  const dates = performance.now() - t0;
  t0 = performance.now();
  for (let i = 0; i < 2000; i++) (i * 1.5).toLocaleString();
  const nums = performance.now() - t0;
  t0 = performance.now();
  const text = 'Hello 👋🏽 wörld, नमस्ते! '.repeat(400);
  const n = [...new Intl.Segmenter('en').segment(text)].length;
  const seg = performance.now() - t0;
  assertEq(n, 20 * 400);
  t0 = performance.now();
  const words = [];
  for (let i = 0; i < 2000; i++) words.push('name' + ((i * 7919) % 2000) + (i % 3 ? 'é' : 'E'));
  words.sort(new Intl.Collator('en', { numeric: true }).compare);
  const sort = performance.now() - t0;
  console.log('intl perf ms: dates ' + dates.toFixed(0) + ', numbers ' + nums.toFixed(0) + ', segment ' + seg.toFixed(0) + ', sort ' + sort.toFixed(0));
  assert(dates < 3000 && nums < 3000 && seg < 5000 && sort < 5000, 'too slow');
});
